const c=$('Procesar Cita Creada').first().json.cita||{};
const r=$('Normalizar Request APP').first().json;
if (!c.id || !c.person_id || !c.starts_at || !r.telefono) return [];
return [{json:{tipo:'cita_agendada',paciente_id:String(c.person_id),cita_id:String(c.id),telefono:r.telefono,starts_at:c.starts_at,modalidad:r.modalidad}}];

const r=$('Preparar Estado Pago').first().json;
const req=$('Normalizar Request APP').first().json;
if (r.estado_pago!=='pagado' || !(Number(r.monto)>0) || !r.telefono || !r.paciente_id) return [];
const row=$input.first().json;
if (row.estado_pago!=='pagado' || String(row.cita_id)!==String(r.cita_id)) return [];
let starts_at=String(r.fecha||'');
if (/^\d{4}-\d{2}-\d{2}$/.test(starts_at) && /^\d{2}:\d{2}$/.test(String(r.hora||''))) starts_at+=`T${r.hora}:00-06:00`;
if (!/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:?\d{2})$/.test(starts_at) || !Number.isFinite(Date.parse(starts_at))) return [];
return [{json:{tipo:'pago_confirmado',paciente_id:r.paciente_id,cita_id:r.cita_id,telefono:r.telefono,starts_at,modalidad:req.modalidad,monto:Number(r.monto)}}];
